class Product extends DataClass implements Insertable<Product> {
  final int id;
  final String? sku;
  final String? barcode;
  final String name;
  final String? nameAr;
  final String? nameFr;
  final String? description;
  final int? categoryId;
  final int? supplierId;
  final Decimal costCents;
  final Decimal priceCents;
  final Decimal? wholesalePriceCents;
  final Decimal? previousCostCents;
  final Decimal? previousPriceCents;
  final Decimal? previousWholesalePriceCents;

  /// Supplier reference price — the **gross** unit cost the user paid on the
  /// most recent purchase line, **before** any per-line trade discount.
  ///
  /// Decouples the user-facing "آخر سعر شراء" UX from the IAS-2-compliant
  /// inventory cost basis stored in [costCents]:
  ///   * [costCents]                = net of discounts → drives COGS,
  ///                                  inventory valuation, GL reconciliation.
  ///   * [lastPurchasePriceCents]   = gross/list price → drives the product
  ///                                  edit screen, margin display, pricing
  ///                                  analysis, supplier negotiation.
  ///
  /// Nullable for backwards compatibility — legacy products predating this
  /// column display [costCents] as a fallback. Populated automatically on
  /// every purchase post (gross unit cost typed by the user) and propagated
  /// to the parent products row via `ProductCostService.syncProductFromVariants`.
  final Decimal? lastPurchasePriceCents;
  final int? currencyId;
  final bool trackInventory;

  /// Stock dimension. `piece` keeps legacy whole-unit behaviour; measured
  /// dimensions store one major unit as 1000 integer stock units.
  final String measurementType;
  final int stockQuantity;
  final int minQuantity;
  final bool hasVariants;
  final bool isTaxable;
  final int purchaseTaxRateBps;
  final int salesTaxRateBps;
  final String? imagePath;
  final bool isActive;

  /// Costing method for inventory valuation. One of:
  ///   - 'wac'  → Weighted Average Cost (default; uses [costCents])
  ///   - 'fifo' → First-In, First-Out (uses [ProductBatches] + [BatchConsumptions])
  /// Locked once any batch consumption exists for this product.
  ///
  /// **DEPRECATED (Phase B+, two-layer inventory architecture).**
  /// New code should:
  ///   * Read the **global** valuation method from `InventoryValuationService`.
  ///   * Read the **per-product** batch policy from [inventoryTrackingType].
  /// This column is preserved for one release for offline-installed apps and
  /// for the Phase B migration's backfill query. Reads from runtime code are
  /// being removed in Phase D/F.
  final String costingMethod;

  /// Inventory tracking type — the per-product batch/expiry policy.
  ///
  /// One of:
  ///   - `'standard'`     → single stock pool, no batches. Cheapest path,
  ///                        suitable for non-perishables (e.g. mug, cable).
  ///   - `'batch'`        → every purchase creates a [ProductBatches] row;
  ///                        consumption is FIFO by `received_date`.
  ///                        Suitable for lot-tracked goods without expiry.
  ///   - `'batch_expiry'` → batch + required `expiry_date`; consumption is
  ///                        FEFO (First-Expired-First-Out) automatically via
  ///                        `BatchService.consumeFifo`. Required for
  ///                        pharmacies, dairy, cosmetics, chemicals.
  ///
  /// Locked once any batch row or stock movement exists for this product.
  ///
  /// Backfilled in migration v10048 from the legacy [costingMethod] column:
  ///   * `wac`  → `standard`
  ///   * `fifo` + ∃ batch with expiry → `batch_expiry`
  ///   * `fifo` (no expiry) → `batch`
  final String inventoryTrackingType;
  final DateTime createdAt;
  final DateTime updatedAt;
  const Product({
    required this.id,
    this.sku,
    this.barcode,
    required this.name,
    this.nameAr,
    this.nameFr,
    this.description,
    this.categoryId,
    this.supplierId,
    required this.costCents,
    required this.priceCents,
    this.wholesalePriceCents,
    this.previousCostCents,
    this.previousPriceCents,
    this.previousWholesalePriceCents,
    this.lastPurchasePriceCents,
    this.currencyId,
    required this.trackInventory,
    required this.measurementType,
    required this.stockQuantity,
    required this.minQuantity,
    required this.hasVariants,
    required this.isTaxable,
    required this.purchaseTaxRateBps,
    required this.salesTaxRateBps,
    this.imagePath,
    required this.isActive,
    required this.costingMethod,
    required this.inventoryTrackingType,
    required this.createdAt,
    required this.updatedAt,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<int>(id);
    if (!nullToAbsent || sku != null) {
      map['sku'] = Variable<String>(sku);
    }
    if (!nullToAbsent || barcode != null) {
      map['barcode'] = Variable<String>(barcode);
    }
    map['name'] = Variable<String>(name);
    if (!nullToAbsent || nameAr != null) {
      map['name_ar'] = Variable<String>(nameAr);
    }
    if (!nullToAbsent || nameFr != null) {
      map['name_fr'] = Variable<String>(nameFr);
    }
    if (!nullToAbsent || description != null) {
      map['description'] = Variable<String>(description);
    }
    if (!nullToAbsent || categoryId != null) {
      map['category_id'] = Variable<int>(categoryId);
    }
    if (!nullToAbsent || supplierId != null) {
      map['supplier_id'] = Variable<int>(supplierId);
    }
    {
      map['cost_cents'] = Variable<int>(
        $ProductsTable.$convertercostCents.toSql(costCents),
      );
    }
    {
      map['price_cents'] = Variable<int>(
        $ProductsTable.$converterpriceCents.toSql(priceCents),
      );
    }
    if (!nullToAbsent || wholesalePriceCents != null) {
      map['wholesale_price_cents'] = Variable<int>(
        $ProductsTable.$converterwholesalePriceCentsn.toSql(
          wholesalePriceCents,
        ),
      );
    }
    if (!nullToAbsent || previousCostCents != null) {
      map['previous_cost_cents'] = Variable<int>(
        $ProductsTable.$converterpreviousCostCentsn.toSql(previousCostCents),
      );
    }
    if (!nullToAbsent || previousPriceCents != null) {
      map['previous_price_cents'] = Variable<int>(
        $ProductsTable.$converterpreviousPriceCentsn.toSql(previousPriceCents),
      );
    }
    if (!nullToAbsent || previousWholesalePriceCents != null) {
      map['previous_wholesale_price_cents'] = Variable<int>(
        $ProductsTable.$converterpreviousWholesalePriceCentsn.toSql(
          previousWholesalePriceCents,
        ),
      );
    }
    if (!nullToAbsent || lastPurchasePriceCents != null) {
      map['last_purchase_price_cents'] = Variable<int>(
        $ProductsTable.$converterlastPurchasePriceCentsn.toSql(
          lastPurchasePriceCents,
        ),
      );
    }
    if (!nullToAbsent || currencyId != null) {
      map['currency_id'] = Variable<int>(currencyId);
    }
    map['track_inventory'] = Variable<bool>(trackInventory);
    map['measurement_type'] = Variable<String>(measurementType);
    map['stock_quantity'] = Variable<int>(stockQuantity);
    map['min_quantity'] = Variable<int>(minQuantity);
    map['has_variants'] = Variable<bool>(hasVariants);
    map['is_taxable'] = Variable<bool>(isTaxable);
    map['purchase_tax_rate_bps'] = Variable<int>(purchaseTaxRateBps);
    map['sales_tax_rate_bps'] = Variable<int>(salesTaxRateBps);
    if (!nullToAbsent || imagePath != null) {
      map['image_path'] = Variable<String>(imagePath);
    }
    map['is_active'] = Variable<bool>(isActive);
    map['costing_method'] = Variable<String>(costingMethod);
    map['inventory_tracking_type'] = Variable<String>(inventoryTrackingType);
    map['created_at'] = Variable<DateTime>(createdAt);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    return map;
  }

  ProductsCompanion toCompanion(bool nullToAbsent) {
    return ProductsCompanion(
      id: Value(id),
      sku: sku == null && nullToAbsent ? const Value.absent() : Value(sku),
      barcode: barcode == null && nullToAbsent
          ? const Value.absent()
          : Value(barcode),
      name: Value(name),
      nameAr: nameAr == null && nullToAbsent
          ? const Value.absent()
          : Value(nameAr),
