          : Value(nameFr),
      description: description == null && nullToAbsent
          ? const Value.absent()
          : Value(description),
      categoryId: categoryId == null && nullToAbsent
          ? const Value.absent()
          : Value(categoryId),
      supplierId: supplierId == null && nullToAbsent
          ? const Value.absent()
          : Value(supplierId),
      costCents: Value(costCents),
      priceCents: Value(priceCents),
      wholesalePriceCents: wholesalePriceCents == null && nullToAbsent
          ? const Value.absent()
          : Value(wholesalePriceCents),
      previousCostCents: previousCostCents == null && nullToAbsent
          ? const Value.absent()
          : Value(previousCostCents),
      previousPriceCents: previousPriceCents == null && nullToAbsent
          ? const Value.absent()
          : Value(previousPriceCents),
      previousWholesalePriceCents:
          previousWholesalePriceCents == null && nullToAbsent
          ? const Value.absent()
          : Value(previousWholesalePriceCents),
      lastPurchasePriceCents: lastPurchasePriceCents == null && nullToAbsent
          ? const Value.absent()
          : Value(lastPurchasePriceCents),
      currencyId: currencyId == null && nullToAbsent
          ? const Value.absent()
          : Value(currencyId),
      trackInventory: Value(trackInventory),
      measurementType: Value(measurementType),
      stockQuantity: Value(stockQuantity),
      minQuantity: Value(minQuantity),
      hasVariants: Value(hasVariants),
      isTaxable: Value(isTaxable),
      purchaseTaxRateBps: Value(purchaseTaxRateBps),
      salesTaxRateBps: Value(salesTaxRateBps),
      imagePath: imagePath == null && nullToAbsent
          ? const Value.absent()
          : Value(imagePath),
      isActive: Value(isActive),
      costingMethod: Value(costingMethod),
      inventoryTrackingType: Value(inventoryTrackingType),
      createdAt: Value(createdAt),
      updatedAt: Value(updatedAt),
    );
  }

