    required this.currencyId,
    required this.paymentMethod,
    required this.status,
    this.notes,
    this.idempotencyKey,
    required this.saleDate,
    this.dueDate,
    this.pricingEngineVersion,
    this.taxInclusiveAtPost,
    this.roundingModeAtPost,
    required this.createdAt,
    required this.updatedAt,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<int>(id);
    map['invoice_number'] = Variable<String>(invoiceNumber);
    if (!nullToAbsent || customerId != null) {
      map['customer_id'] = Variable<int>(customerId);
    }
    if (!nullToAbsent || employeeId != null) {
      map['employee_id'] = Variable<int>(employeeId);
    }
    if (!nullToAbsent || cashierShiftId != null) {
      map['cashier_shift_id'] = Variable<int>(cashierShiftId);
    }
    {
      map['subtotal_cents'] = Variable<int>(
        $SalesTable.$convertersubtotalCents.toSql(subtotalCents),
      );
    }
    {
      map['tax_cents'] = Variable<int>(
        $SalesTable.$convertertaxCents.toSql(taxCents),
      );
