          ..write('code: $code, ')
          ..write('labelEn: $labelEn, ')
          ..write('labelAr: $labelAr, ')
          ..write('side: $side, ')
          ..write('isActive: $isActive, ')
          ..write('isSystem: $isSystem, ')
          ..write('description: $description, ')
          ..write('createdAt: $createdAt, ')
          ..write('updatedAt: $updatedAt')
          ..write(')'))
        .toString();
  }
