class PurchaseItem extends DataClass implements Insertable<PurchaseItem> {
  final int id;
  final int purchaseId;
  final int productId;
  final int? variantId;
  final int quantity;
  final int quantityScale;
  final String measurementType;
  final Decimal unitCostCents;

  /// Exact rounded-pool value added to inventory when this purchase posted.
  final Decimal? inventoryValueAtPostCents;
  final Decimal discountCents;
  final Decimal subtotalCents;
  final Decimal taxCents;
  final Decimal totalCents;
  final Decimal? originalCostCents;
  final Decimal? originalPriceCents;
  final Decimal? originalWholesalePriceCents;
  final Decimal? newSellPriceCents;
  final Decimal? newWholesalePriceCents;
  final DateTime? expiryDate;

  /// Atomic returned-quantity counter (linked path).
  /// Bumped inside `postPurchaseReturn`, decremented inside `voidPurchaseReturn`.
  /// Phase 0 server-side cap to stop over-returning across multiple invoices.
  final int qtyReturnedLinked;

  /// Atomic returned-quantity counter (adjustment / unlinked path).
  /// Bumped inside `postPurchaseAdjReturn`, decremented inside `voidPurchaseAdjReturn`.
  /// Combined with `qtyReturnedLinked` to form the total returned units.
  final int qtyReturnedAdjustment;
  final DateTime createdAt;
  const PurchaseItem({
    required this.id,
    required this.purchaseId,
    required this.productId,
    this.variantId,
    required this.quantity,
    required this.quantityScale,
    required this.measurementType,
    required this.unitCostCents,
    this.inventoryValueAtPostCents,
    required this.discountCents,
    required this.subtotalCents,
    required this.taxCents,
    required this.totalCents,
    this.originalCostCents,
    this.originalPriceCents,
    this.originalWholesalePriceCents,
    this.newSellPriceCents,
    this.newWholesalePriceCents,
    this.expiryDate,
    required this.qtyReturnedLinked,
    required this.qtyReturnedAdjustment,
    required this.createdAt,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<int>(id);
    map['purchase_id'] = Variable<int>(purchaseId);
    map['product_id'] = Variable<int>(productId);
    if (!nullToAbsent || variantId != null) {
      map['variant_id'] = Variable<int>(variantId);
    }
    map['quantity'] = Variable<int>(quantity);
    map['quantity_scale'] = Variable<int>(quantityScale);
    map['measurement_type'] = Variable<String>(measurementType);
    {
      map['unit_cost_cents'] = Variable<int>(
        $PurchaseItemsTable.$converterunitCostCents.toSql(unitCostCents),
      );
    }
    if (!nullToAbsent || inventoryValueAtPostCents != null) {
      map['inventory_value_at_post_cents'] = Variable<int>(
        $PurchaseItemsTable.$converterinventoryValueAtPostCentsn.toSql(
          inventoryValueAtPostCents,
        ),
      );
    }
    {
      map['discount_cents'] = Variable<int>(
        $PurchaseItemsTable.$converterdiscountCents.toSql(discountCents),
      );
    }
    {
      map['subtotal_cents'] = Variable<int>(
        $PurchaseItemsTable.$convertersubtotalCents.toSql(subtotalCents),
      );
    }
    {
      map['tax_cents'] = Variable<int>(
        $PurchaseItemsTable.$convertertaxCents.toSql(taxCents),
      );
    }
    {
      map['total_cents'] = Variable<int>(
        $PurchaseItemsTable.$convertertotalCents.toSql(totalCents),
      );
    }
    if (!nullToAbsent || originalCostCents != null) {
      map['original_cost_cents'] = Variable<int>(
        $PurchaseItemsTable.$converteroriginalCostCentsn.toSql(
          originalCostCents,
        ),
      );
    }
    if (!nullToAbsent || originalPriceCents != null) {
      map['original_price_cents'] = Variable<int>(
        $PurchaseItemsTable.$converteroriginalPriceCentsn.toSql(
          originalPriceCents,
        ),
      );
    }
    if (!nullToAbsent || originalWholesalePriceCents != null) {
      map['original_wholesale_price_cents'] = Variable<int>(
        $PurchaseItemsTable.$converteroriginalWholesalePriceCentsn.toSql(
          originalWholesalePriceCents,
        ),
      );
    }
    if (!nullToAbsent || newSellPriceCents != null) {
      map['new_sell_price_cents'] = Variable<int>(
        $PurchaseItemsTable.$converternewSellPriceCentsn.toSql(
          newSellPriceCents,
        ),
      );
    }
    if (!nullToAbsent || newWholesalePriceCents != null) {
      map['new_wholesale_price_cents'] = Variable<int>(
        $PurchaseItemsTable.$converternewWholesalePriceCentsn.toSql(
          newWholesalePriceCents,
        ),
      );
    }
    if (!nullToAbsent || expiryDate != null) {
      map['expiry_date'] = Variable<DateTime>(expiryDate);
    }
    map['qty_returned_linked'] = Variable<int>(qtyReturnedLinked);
    map['qty_returned_adjustment'] = Variable<int>(qtyReturnedAdjustment);
    map['created_at'] = Variable<DateTime>(createdAt);
    return map;
  }

  PurchaseItemsCompanion toCompanion(bool nullToAbsent) {
    return PurchaseItemsCompanion(
      id: Value(id),
      purchaseId: Value(purchaseId),
      productId: Value(productId),
      variantId: variantId == null && nullToAbsent
          ? const Value.absent()
          : Value(variantId),
      quantity: Value(quantity),
      quantityScale: Value(quantityScale),
      measurementType: Value(measurementType),
      unitCostCents: Value(unitCostCents),
      inventoryValueAtPostCents:
          inventoryValueAtPostCents == null && nullToAbsent
          ? const Value.absent()
          : Value(inventoryValueAtPostCents),
      discountCents: Value(discountCents),
      subtotalCents: Value(subtotalCents),
      taxCents: Value(taxCents),
      totalCents: Value(totalCents),
      originalCostCents: originalCostCents == null && nullToAbsent
          ? const Value.absent()
          : Value(originalCostCents),
      originalPriceCents: originalPriceCents == null && nullToAbsent
          ? const Value.absent()
          : Value(originalPriceCents),
      originalWholesalePriceCents:
          originalWholesalePriceCents == null && nullToAbsent
          ? const Value.absent()
          : Value(originalWholesalePriceCents),
      newSellPriceCents: newSellPriceCents == null && nullToAbsent
          ? const Value.absent()
          : Value(newSellPriceCents),
      newWholesalePriceCents: newWholesalePriceCents == null && nullToAbsent
          ? const Value.absent()
          : Value(newWholesalePriceCents),
      expiryDate: expiryDate == null && nullToAbsent
          ? const Value.absent()
          : Value(expiryDate),
      qtyReturnedLinked: Value(qtyReturnedLinked),
      qtyReturnedAdjustment: Value(qtyReturnedAdjustment),
      createdAt: Value(createdAt),
    );
  }

