          : Value(variantId),
      templateId: templateId == null && nullToAbsent
          ? const Value.absent()
          : Value(templateId),
      quantityPrinted: Value(quantityPrinted),
      printerName: printerName == null && nullToAbsent
          ? const Value.absent()
          : Value(printerName),
      printType: Value(printType),
      status: Value(status),
      errorMessage: errorMessage == null && nullToAbsent
