    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'id': serializer.toJson<int>(id),
      'adjustmentNumber': serializer.toJson<String>(adjustmentNumber),
      'productId': serializer.toJson<int>(productId),
      'variantId': serializer.toJson<int?>(variantId),
      'adjustmentType': serializer.toJson<String>(adjustmentType),
      'quantityDelta': serializer.toJson<int>(quantityDelta),
      'unitCostCents': serializer.toJson<Decimal>(unitCostCents),
      'totalValueCents': serializer.toJson<Decimal>(totalValueCents),
      'previousUnitCostCents': serializer.toJson<Decimal?>(
        previousUnitCostCents,
      ),
      'reason': serializer.toJson<String>(reason),
      'notes': serializer.toJson<String?>(notes),
      'currencyId': serializer.toJson<int>(currencyId),
      'userId': serializer.toJson<int?>(userId),
      'journalEntryId': serializer.toJson<int?>(journalEntryId),
      'costingMethod': serializer.toJson<String>(costingMethod),
      'createdAt': serializer.toJson<DateTime>(createdAt),
      'updatedAt': serializer.toJson<DateTime>(updatedAt),
    };
  }

